update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png" alt="Месяц силы" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве силы, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию третьей чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png" alt="Месяц силы" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве силы, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию третьей чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png","alt":"Месяц силы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":125},{"id":"month-strength-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве силы, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию третьей чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='b52b80a0-67b9-5e76-9cc6-e4887b467ff1';

update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png" alt="Месяц силы" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Уже прошли три недели Месяца силы. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Открыть урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png" alt="Месяц силы" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Уже прошли три недели Месяца силы. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Открыть урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
