update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png" alt="Месяц силы" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё один дополнительный урок, направленный на гармонизацию третьей чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png" alt="Месяц силы" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё один дополнительный урок, направленный на гармонизацию третьей чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png","alt":"Месяц силы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":125},{"id":"month-strength-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё один дополнительный урок, направленный на гармонизацию третьей чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='84a93dad-88bd-589c-a284-f66d491759f7';

update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png" alt="Месяц силы" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию третьей чакры, то есть на здоровье органов ЖКТ, а также психологическое и поведенческое оздоравливание своей проявленности в этом мире, интеграции в социум, осуществления своих желаний, ответственности, лидерства, личной силы...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Открыть урок 5</a></p><p></p><p>И я приглашаю вас в дальнейший путь. На странице урока вы найдёте несколько версий продолжения Пути. Ну а пока самое очевидное... За месяц вы очистили и гармонизировали манипуру настолько, насколько это возможно в данное время. И это хороший фундамент для того, чтобы перейти на уровень анахаты (чакры любви), и проработать её сферы. Продолжайте движение, присоединяйтесь к практикам Месяца любви. Чтобы ознакомиться с описанием, нажмите кнопку...</p><p></p><p>Месяц любви - <a href="https://zamkovoi.yoga/m4/">https://zamkovoi.yoga/m4/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png" alt="Месяц силы" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию третьей чакры, то есть на здоровье органов ЖКТ, а также психологическое и поведенческое оздоравливание своей проявленности в этом мире, интеграции в социум, осуществления своих желаний, ответственности, лидерства, личной силы...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly">Открыть урок 5</a></p><p></p><p>И я приглашаю вас в дальнейший путь. На странице урока вы найдёте несколько версий продолжения Пути. Ну а пока самое очевидное... За месяц вы очистили и гармонизировали манипуру настолько, насколько это возможно в данное время. И это хороший фундамент для того, чтобы перейти на уровень анахаты (чакры любви), и проработать её сферы. Продолжайте движение, присоединяйтесь к практикам Месяца любви. Чтобы ознакомиться с описанием, нажмите кнопку...</p><p></p><p>Месяц любви - <a href="https://zamkovoi.yoga/m4/">https://zamkovoi.yoga/m4/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-strength-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/campaigns/1795005080738-natxf3.png","alt":"Месяц силы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":125},{"id":"month-strength-07-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию третьей чакры, то есть на здоровье органов ЖКТ, а также психологическое и поведенческое оздоравливание своей проявленности в этом мире, интеграции в социум, осуществления своих желаний, ответственности, лидерства, личной силы...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#F89C26;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#F89C26;mso-line-height-rule:exactly\">Открыть урок 5</a></p><p></p><p>И я приглашаю вас в дальнейший путь. На странице урока вы найдёте несколько версий продолжения Пути. Ну а пока самое очевидное... За месяц вы очистили и гармонизировали манипуру настолько, насколько это возможно в данное время. И это хороший фундамент для того, чтобы перейти на уровень анахаты (чакры любви), и проработать её сферы. Продолжайте движение, присоединяйтесь к практикам Месяца любви. Чтобы ознакомиться с описанием, нажмите кнопку...</p><p></p><p>Месяц любви - <a href=\"https://zamkovoi.yoga/m4/\">https://zamkovoi.yoga/m4/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='6bdc99e1-38eb-5ca1-aa0c-3774974b4724';
